# Runs the unit tests under LuaCov and checks the line coverage of StatsTrimmer/.
# Generated files (Locales.lua, FoodData.lua: those whose first line says "Generated by") are mostly data, which
# any spec that loads them covers whole, so they are counted apart: the minimum applies to the hand-written code.
# Needs LuaJIT and LuaCov 0.17.0: its src folder in %LOCALAPPDATA%\Programs\luacov, or the one given with -LuaCov
# (see docs/DEVELOPMENT.md).
# Usage: ./scripts/coverage.ps1 [-Minimum 95] [-LuaCov <path to LuaCov's src folder>]
param([double]$Minimum = 95, [string]$LuaCov = (Join-Path $env:LOCALAPPDATA "Programs\luacov"))

$root = Split-Path -Parent $PSScriptRoot
$luacov = $LuaCov -replace '\\', '/'
$setPath = "package.path='$luacov/?.lua;'..package.path"

# Hits and missed lines of a group of report rows, with its coverage
function Measure-Group([object[]]$rows) {
	$hits = ($rows | Measure-Object -Property Hits -Sum).Sum
	$missed = ($rows | Measure-Object -Property Missed -Sum).Sum
	$lines = $hits + $missed
	$coverage = if ($lines -gt 0) { [math]::Round(100 * $hits / $lines, 2) } else { 100 }
	return [pscustomobject]@{ Lines = $lines; Missed = $missed; Coverage = $coverage }
}

Push-Location $root
try {
	Remove-Item luacov.stats.out, luacov.report.out -ErrorAction SilentlyContinue
	$specs = Get-ChildItem spec -Filter *_spec.lua | ForEach-Object { "spec/$($_.Name)" }

	# -joff: LuaJIT's compiled code doesn't fire the line hooks LuaCov counts with
	luajit -joff -e $setPath -lluacov spec/runner.lua @specs
	if ($LASTEXITCODE -ne 0) {
		exit $LASTEXITCODE
	}
	luajit -e $setPath "$luacov/bin/luacov"

	# The report ends with a Summary table: "<file> <hits> <missed> <coverage>%" rows and a Total row
	$summary = ((Get-Content luacov.report.out -Raw) -split '(?m)^Summary\s*$')[-1]
	$lines = @($summary -split "`r?`n" | Where-Object { $_ -match '^StatsTrimmer[\\/]\S+\s+\d+\s+\d+\s+[\d.]+%' })
	if ($lines.Count -eq 0) {
		Write-Output "The coverage report has no StatsTrimmer files"
		exit 1
	}
	$lines | ForEach-Object { $_ }
	$rows = foreach ($line in $lines) {
		$path, $hits, $missed = ($line -split '\s+')[0..2]
		$path = $path -replace '\\', '/'
		$generated = (Get-Content $path -TotalCount 1) -like '-- Generated by *'
		[pscustomobject]@{ Path = $path; Hits = [int]$hits; Missed = [int]$missed; Generated = $generated }
	}

	$handWritten = Measure-Group @($rows | Where-Object { -not $_.Generated })
	$generated = Measure-Group @($rows | Where-Object { $_.Generated })
	Write-Output ("Generated files: {0}% of {1} lines" -f $generated.Coverage, $generated.Lines)
	Write-Output ("Hand-written code: {0}% of {1} lines" -f $handWritten.Coverage, $handWritten.Lines)
	if ($handWritten.Coverage -lt $Minimum) {
		Write-Output ("Hand-written coverage {0}% is below the {1}% minimum" -f $handWritten.Coverage, $Minimum)
		exit 1
	}
	Write-Output ("Coverage {0}% (minimum {1}%)" -f $handWritten.Coverage, $Minimum)
	exit 0
}
finally {
	Pop-Location
}
